create table public.trade_proposal_producer_evaluations(id uuid primary key default gen_random_uuid(),evaluation_key text not null unique,policy_version text not null,opportunity_id uuid not null references public.opportunities(id),meta_assessment_id uuid references public.meta_assessments(id),consensus_snapshot_id uuid references public.consensus_snapshots(id),decision text not null check(decision in('PROPOSAL_READY','REJECTED','DATA_BLOCKED')),requirements jsonb not null,evidence_refs jsonb not null,trade_proposal_id uuid references public.trade_proposals(id),information_cutoff_at timestamptz not null,available_at timestamptz not null,result_hash text not null,created_at timestamptz not null default now(),check(information_cutoff_at<=available_at),unique(opportunity_id,policy_version,information_cutoff_at));create index trade_proposal_producer_decision_idx on public.trade_proposal_producer_evaluations(decision,created_at desc);create trigger trade_proposal_producer_immutable before update or delete on public.trade_proposal_producer_evaluations for each row execute function public.prevent_execution_history_mutation();alter table public.trade_proposal_producer_evaluations enable row level security;create policy "public read proposal producer" on public.trade_proposal_producer_evaluations for select using(true);grant select on public.trade_proposal_producer_evaluations to anon,authenticated;grant all on public.trade_proposal_producer_evaluations to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast','forecast_performance','forecast_scheduler','forecast_outcomes','specialist_agents','news_ingestion','catalyst_classification','consensus','agent_performance','market_regime','meta_agent','meta_readiness','strategy_pattern_lab','candle_ingestion','ai_explanations','strategy_intelligence','execution','trade_eligibility','account_state','execution_bridge','trade_proposal_producer'));
